#!/usr/bin/env python3
"""Offline coefficients: no trigonometry/floating point in firmware DSP."""
from pathlib import Path
import math

out = Path(__file__).resolve().parents[1] / "dsp/tables.hpp"
lines = [
    "// Generated by tools/generate_tables.py; do not edit by hand.",
    "#pragma once",
    "#include <cstdint>",
    "namespace mtm { namespace tables {",
]


def array(name, values, kind="int32_t"):
    lines.append(f"inline constexpr {kind} {name}[{len(values)}] = {{")
    for i in range(0, len(values), 12):
        lines.append(" " + ",".join(str(round(x)) for x in values[i : i + 12]) + ",")
    lines.append("};")


weights = []
for i in range(256):
    f = i / 256
    weights += [
        8192 * -f * (f - 1) * (f - 2) / 6,
        8192 * (f + 1) * (f - 1) * (f - 2) / 2,
        8192 * -(f + 1) * f * (f - 2) / 2,
        8192 * (f + 1) * f * (f - 1) / 6,
    ]
array("cubic", weights, "int16_t")
for name, a in [("ratio035", 0.035), ("ratio020", 0.02), ("ratio003", 0.003)]:
    array(name, [32768 * (i / 256) / (a + i / 256) for i in range(257)], "uint16_t")
array("limiter", [32768 * 0.85 * (i / 256) / (1 + i / 256) for i in range(1025)])
array("period", [24000 / 261.625565 * 65536 * 2 ** (-i / 1024) for i in range(1025)])
# Fundamental phase delay for one-pole loss + allpass, 33 String brightness x 65 Hz bins.
# The phase law is compensated without evaluating trigonometry on the MCU.
comp = []
for mi in range(33):
    a = 0.3
    pole = 1 - (0.82 + 0.175 * mi / 32)
    for fi in range(65):
        f = 40 + fi * (1960 / 64)
        omega = 2 * math.pi * f / 24000
        real = (1 + a * a) * math.cos(omega) - 2 * a
        imag = -(1 - a * a) * math.sin(omega)
        phase = math.atan2(imag, real)
        lossPhase = math.atan2(-pole * math.sin(omega), 1 - pole * math.cos(omega))
        comp.append(4096 * (-phase - lossPhase) / omega)
array("delayComp", comp, "int16_t")
# Q15 FIR, 17-tap Blackman halfband, unity gain; alternating taps almost zero.
h = []
for i in range(17):
    d = i - 8
    v = 0.5 if d == 0 else math.sin(math.pi * 0.5 * d) / (math.pi * d)
    h.append(
        v
        * (
            0.42
            - 0.5 * math.cos(2 * math.pi * i / 16)
            + 0.08 * math.cos(4 * math.pi * i / 16)
        )
    )
h = [round(x / sum(h) * 32768) for x in h]
h[8] += 32768 - sum(h)
array("halfband", h, "int16_t")
# Finite mizrab release at strength1: 2.2ms, native53samples.
array(
    "pickWindow",
    [32768 * (i / 52) / (0.045 + i / 52) * (1 - i / 52) ** 2 for i in range(53)],
    "int16_t",
)
array(
    "pickPulse",
    [32768 * 6 * (i / 52) * (1 - i / 52) * (1 - 2 * i / 52) for i in range(53)],
    "int16_t",
)
# 12 strings, 5 odd partials, two damped resonators per partial.
fundamentals = [
    146.8324,
    164.8138,
    174.6141,
    195.9977,
    220,
    233.0819,
    261.6256,
    293.6648,
    329.6276,
    349.2282,
    440,
    587.3295,
]
rows = []
for i, f0 in enumerate(fundamentals):
    for j, harm in enumerate([1, 3, 5, 7, 9]):
        f = f0 * harm * math.sqrt(1 + 0.00004 * (harm * harm - 1))
        tau = (3.6 - 0.08 * i) / (1 + (0.08) * (harm - 1))
        r = math.exp(-1 / (12000 * tau))
        tauFast = 0.12 + 0.045 * ((i + 2 * j) % 9)
        fast = math.exp(-1 / (12000 * tauFast))
        omega = 2 * math.pi * f / 12000
        # Sine resonator response has gain 1/sin(w); normalise the excitation so
        # partial radiation retains the same target amplitude across the bank.
        gain = (
            0.065 * math.sqrt(1 - r) * [0.12, 0.55, 1, 1.15, 0.85][j] * math.sin(omega)
        )
        rows += [
            round(16384 * 2 * r * math.cos(omega)),
            round((1 - r * r) * 16777216),
            round(16384 * 2 * fast * math.cos(omega)),
            round((1 - fast * fast) * 16777216),
            round(gain * 262144 * 8),
        ]
array("modal", rows)
lines.append("}}")
out.write_text("\n".join(lines) + "\n")
print("Generated", out)
